<template><section class="storage-view" v-loading="busy"><header><div><h1>题包归档</h1><p>将管理员题包保存到私有 RustFS / S3 桶。包含参考实现和隐藏测试，仅管理员可下载。</p></div><el-button :loading="checking" @click="check">检查连接</el-button></header><el-alert v-if="!state.enabled" type="info" :closable="false" title="对象存储未启用，请在部署配置中设置 S3_ENABLED 和连接信息。"/><template v-else><p>桶：{{state.bucket}} · 区域：{{state.region}} · {{state.pathStyle?'Path Style':'Virtual Host Style'}}</p><div class="archive-form"><el-input v-model="problemId" placeholder="题目 ID" style="width:220px"/><el-button type="primary" :loading="archiving" @click="archive">归档题包</el-button><el-button @click="load">刷新列表</el-button></div><el-table :data="rows"><el-table-column prop="key" label="归档对象" min-width="320"/><el-table-column prop="bytes" label="字节" width="110"/><el-table-column prop="updatedAt" label="归档时间" width="210"/><el-table-column width="100"><template #default="{row}"><el-button link @click="download(row)">下载</el-button></template></el-table-column></el-table><small>按对象名显示最多 100 条。恢复时先下载，再在题库管理中作为新草稿导入并验证；归档不自动覆盖题目。</small></template></section></template>
<script setup>
import {ref,onMounted} from 'vue'
import {ElMessage} from 'element-plus'
import request from '@/utils/request'
const state=ref({enabled:false}),rows=ref([]),problemId=ref(''),busy=ref(false),checking=ref(false),archiving=ref(false)
async function load(){busy.value=true;try{const r=await request.get('/api/admin/storage');state.value=r.data;if(state.value.enabled)rows.value=(await request.get('/api/admin/storage/archives')).data}finally{busy.value=false}}
async function check(){checking.value=true;try{await request.post('/api/admin/storage/check');ElMessage.success('连接和桶权限正常');await load()}finally{checking.value=false}}
async function archive(){if(!/^[1-9][0-9]*$/.test(problemId.value)){ElMessage.warning('请输入题目 ID');return}archiving.value=true;try{await request.post(`/api/admin/storage/problems/${problemId.value}/archive`);ElMessage.success('已归档');await load()}finally{archiving.value=false}}
async function download(row){const id=row.key.split('/').pop().replace('.json','');const response=await request.get(`/api/admin/storage/archives/${id}`,{responseType:'blob'});const url=URL.createObjectURL(new Blob([response],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`${id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
onMounted(load)
</script>
<style scoped>.storage-view{background:#fff;border:1px solid #e3e8f0;border-radius:16px;padding:28px}.storage-view header{display:flex;align-items:center;justify-content:space-between;gap:20px}.storage-view h1{font-size:25px;color:#283d58}.storage-view p,.storage-view small{font-size:13px;line-height:1.8;color:#8193aa}.archive-form{display:flex;gap:14px;margin:24px 0}</style>
